<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
acHandle(function()use($ac){return match($_POST['action']??''){'settings'=>$ac->saveSettings($_POST),'period'=>$ac->savePeriod($_POST),'method'=>$ac->saveMethod($_POST),'period_state'=>$ac->closePeriod((int)$_POST['period_id'],!empty($_POST['close']),$_POST['reason']??'',!empty($_POST['confirm'])),default=>throw new InvalidArgumentException('Unsupported accounting setting.')};},'settings');$periods=$ac->rows('SELECT * FROM ac_periods WHERE school_id=? ORDER BY start_date DESC',[$school]);ob_start();
?>
<p>Configure actual fiscal dates before issuing bills or posting transactions. Fiscal periods are separate from academic sessions. No tax rate, school fee, fine policy or gateway is assumed.</p>
<?php if($ac->can('settings')): ?><?php acForm('settings','School billing & numbering');acInput('pan_number','PAN / applicable tax registration number',$ac->settings['pan_number']??'','text',false); ?><label class="mb-3"><input type="checkbox" name="tax_registered" value="1" <?= $ac->settings['tax_registered']?'checked':'' ?>> School is configured for legally applicable taxes (rates set per item)</label><div class="row"><div class="col-md-6"><?php acInput('invoice_prefix','Invoice prefix',$ac->settings['invoice_prefix']);acInput('receipt_prefix','Receipt prefix',$ac->settings['receipt_prefix']); ?></div><div class="col-md-6"><?php acInput('due_days','Default due days',(string)$ac->settings['due_days'],'number');acInput('discount_approval','Maximum unapproved manual discount (NPR)',acAmount((int)$ac->settings['discount_approval_minor']),'number'); ?></div></div><label><input type="checkbox" name="prorate" value="1" <?= $ac->settings['prorate']?'checked':'' ?>> Prorate monthly fees by actual calendar days and effective admission/assignment dates</label><?php acSubmit('Save financial settings'); ?>
<?php acForm('period','Add fiscal period');acInput('name','Fiscal year / period name');acInput('start_date','Start date (AD or BS)',date('Y-m-d'),'date');acInput('end_date','End date (AD or BS)',date('Y-m-d',strtotime('+1 year -1 day')),'date');acSubmit('Create non-overlapping fiscal period'); ?>
<details class="mb-3"><summary>Add payment method / bank account mapping</summary><?php acForm('method');acInput('name','Payment method name');acSelect('account_id','Cash / bank asset account',$ac->rows("SELECT * FROM ac_accounts WHERE school_id=? AND type='asset' AND (control_key IS NULL OR control_key IN ('cash','bank')) ORDER BY code",[$school])); ?><label><input type="checkbox" name="requires_reference" value="1"> Require external confirmation and transaction reference</label><?php acSubmit('Create payment method'); ?></details><?php endif; ?>
<div class="card card-body mb-3"><h4>Fiscal period locks</h4><?php foreach($periods as $p): ?><div class="border-bottom mb-3 pb-3"><strong><?= sanitize($p['name']) ?></strong> · <?= sanitize(schoolDateLabel($p['start_date'],'both','ymd')) ?> – <?= sanitize(schoolDateLabel($p['end_date'],'both','ymd')) ?> · <?= $p['is_closed']?'Closed':'Open' ?><?php if($ac->can('period')): ?><form method="post" class="mt-2"><input type="hidden" name="action" value="period_state"><input type="hidden" name="period_id" value="<?= $p['id'] ?>"><input type="hidden" name="close" value="<?= $p['is_closed']?'0':'1' ?>"><?php acInput('reason','Reason for closing / reopening'); ?><label><input type="checkbox" name="confirm" value="1" required> I confirm this fiscal-period change</label><button class="btn btn-sm btn-outline-primary"><?= $p['is_closed']?'Reopen':'Close period' ?></button></form><?php endif; ?></div><?php endforeach; ?><?php if(!$periods): ?><p class="text-warning">No fiscal period configured. Posting is blocked until an administrator adds it.</p><?php endif; ?></div>
<div class="card card-body"><h4>Accounting permissions</h4><p>Administrators: settings, approvals, refunds, reversals and all financial actions. Accountants: catalog, billing, collection and draft expenses. Cashiers: payments, receipts and advance allocation. Auditors: read-only access. Assign roles under Staff accounts.</p><h4>Notification delivery</h4><p>On-screen success/error notifications are active. External email, SMS and WhatsApp delivery is disabled; no gateway or delivery service is configured.</p></div>
<div class="card card-body mt-3 table-responsive"><h4>Accounting audit trail</h4><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Reason</th></tr></thead><tbody><?php foreach($ac->rows('SELECT a.*,u.full_name FROM ac_audit a LEFT JOIN users u ON u.id=a.actor_id WHERE a.school_id=? ORDER BY a.id DESC LIMIT 200',[$school]) as $a): ?><tr><td><?= sanitize($a['created_at']) ?></td><td><?= sanitize($a['full_name']??'#'.$a['actor_id']) ?></td><td><?= sanitize($a['action']) ?></td><td><?= sanitize($a['entity'].' #'.$a['record_id']) ?></td><td><?= sanitize($a['reason']??'') ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Accounting settings & audit',ob_get_clean());
